local a=5;local function b()local c={}for d,e in ipairs(peripheral.getNames())do if peripheral.getType(e)=="thruster"then c[#c+1]=e end end;return c end;local function f(c)local g={}for h,e in ipairs(c)do g[h]=peripheral.wrap(e)end;return g end;local function i(j)local k={}for h=1,#j do k[h]=j[h]end;table.sort(k)return k[math.ceil(#k/2)]end;local function l(g,m)local n=os.epoch("utc")for h=1,m do g[h].setPower(0)end;return os.epoch("utc")-n end;local function o(g,m)local p={}for h=1,m do p[h]=function()g[h].setPower(0)end end;local n=os.epoch("utc")parallel.waitForAll(table.unpack(p,1,m))return os.epoch("utc")-n end;local function q(g,m)local r,s={},{}for d=1,a do r[#r+1]=l(g,m)end;for d=1,a do s[#s+1]=o(g,m)end;return i(r),i(s)end;local function t()local c=b()if#c==0 then print("No 'thruster' peripherals found. Connect the craft's wired network and retry.")return end;local g=f(c)local u=#c;print(("Found %d thruster(s). Measuring sequential vs concurrent setPower(0)."):format(u))print("(all writes are setPower(0) -- nothing fires)\n")print(" N  | sequential | concurrent | seq/write | verdict")print("----+------------+------------+-----------+---------------------------")local v,w={},{}for d,m in ipairs({1,2,4,8,u})do if m>=1 and m<=u and not w[m]then w[m]=true;v[#v+1]=m end end;for d,m in ipairs(v)do local r,s=q(g,m)local x=""if m>1 then if s<=r*0.6 then x="BATCHES (concurrent wins)"elseif s>=r*0.85 then x="no batching"else x="partial"end end;print(("%3d | %7d ms | %7d ms | %6.1f ms | %s"):format(m,r,s,r/m,x))end;for h=1,u do g[h].setPower(0)end;print("\nInterpretation:")print(" - If 'concurrent' stays ~flat (~one tick, ~50-100ms) as N grows while 'sequential'")print("   climbs ~50ms per thruster -> batching works -> the parallel-writer fix will hold ~18Hz.")print(" - If 'concurrent' tracks 'sequential' (both climb with N) -> no batching -> rethink.")end;t()